// Manager · compone la respuesta y el log de trazabilidad (sin IA). Solo lee su entrada.
const r = $input.first().json;
const triaje = r.triaje || {};
const traceId = r.trace_id;
const peticion = r.peticion;
const conc = r.conc || null;
const est = r.est || null;
const escalado = r.escalado === true;

const eur = (n) => {
  const v = Number(n) || 0; const [e, d] = Math.abs(v).toFixed(2).split('.');
  return `${v < 0 ? '-' : ''}${e.replace(/\B(?=(\d{3})+(?!\d))/g, '.')},${d} €`;
};
const fecha = (s) => { const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${m[3]}/${m[2]}/${m[1]}` : String(s || ''); };

const lineas = [];
const workers = [];
let revisiones = [];
if (conc) workers.push(`Worker Conciliación → ${conc.status}${conc.message ? ` (${conc.message})` : ''}`);
if (est) workers.push(`Worker Estado de cuenta → ${est.status}${est.message ? ` (${est.message})` : ''}`);

if (est && est.status === 'success') {
  const d = est.data || {};
  lineas.push(`Cliente: ${d.cliente} | Unidad: ${d.unidad} | Contrato: ${d.contrato_id}`);
  if (conc && conc.status === 'success') {
    const c = conc.data || {};
    const reg = c.registrados || []; const rev = c.en_revision || [];
    const movs = [...reg.map((m) => ({ ...m, estado: 'REGISTRADO' })), ...rev.map((m) => ({ ...m, estado: 'REVISION' }))];
    lineas.push('Movimientos procesados:');
    lineas.push(...(movs.length ? movs.map((m) => `- ${fecha(m.fecha)} · ${eur(m.importe)} · ${m.estado} · ${m.motivo}`) : ['- Sin pagos pendientes de registrar']));
    if (c.sin_procesar_por_limite) lineas.push(`- Quedan ${c.sin_procesar_por_limite} movimientos sin procesar por el límite de 3 por petición.`);
    revisiones = rev.map((m) => ({ ...m, contrato_id: c.contrato_id, cliente: c.cliente, unidad: c.unidad, responsable: c.responsable, importe_exigible: c.importe_exigible, trace_id: traceId }));
  }
  lineas.push(`Situación a ${fecha(d.fecha_corte)}: total ${eur(d.total)}, abonado ${eur(d.total_abonado)}, saldo pendiente ${eur(d.saldo_pendiente)}, vencido ${eur(d.importe_vencido)}${d.proxima_cuota_fecha ? `, próxima cuota ${fecha(d.proxima_cuota_fecha)} por ${eur(d.proxima_cuota_importe)}` : ''}${Number(d.saldo_a_favor) > 0 ? `, saldo a favor ${eur(d.saldo_a_favor)}` : ''}.`);
  lineas.push(`Estado de cuenta: pestaña "Estado de cuenta" de ${d.enlace}`);
  if (revisiones.length) lineas.push(`Pendiente de confirmación por ${revisiones[0].responsable} en Slack (#cobranza-revision).`);
} else if ((conc && conc.status === 'error') || (est && est.status === 'error')) {
  lineas.push(`No he podido completar la petición: ${((est && est.message) || (conc && conc.message)) || 'fallo de un Worker'}.`);
  lineas.push('Escalar a Administración: fallo técnico.');
} else if (escalado) {
  lineas.push(triaje.mensaje || 'Esta petición requiere una decisión humana.');
  lineas.push('He avisado a un supervisor en Slack (#cobranza-revision).');
} else {
  lineas.push(triaje.mensaje || 'No he entendido la petición. Indica el cliente, su NIF o la unidad.');
}

const respuesta = lineas.join('\n');
let estado = `RUTA ${triaje.intencion || 'DESCONOCIDA'}`;
if ((conc && conc.status === 'error') || (est && est.status === 'error')) estado = 'FALLO DE WORKER';
else if (revisiones.length) estado = `REQUIERE REVISIÓN HUMANA (${revisiones.length})`;
else if (conc && conc.data && (conc.data.registrados || []).length) estado = `PAGOS REGISTRADOS (${conc.data.registrados.length})`;

const logSlack = [
  `*Tarea completada* · Manager de Cobranza`,
  `*Estado:* ${estado}`,
  `*Traza:* ${traceId} · ejecución ${$execution.id} · ${$now.toFormat('yyyy-MM-dd HH:mm')}`,
  `*Petición:* ${peticion}`,
  `*Clasificación:* ${triaje.intencion || 'sin clasificar'} · contrato ${triaje.contrato_id || '-'} · ${triaje.motivo_clasificacion || ''}`,
  `*Workers invocados:* ${workers.length ? '' : 'ninguno'}`,
  ...workers.map((w) => `• ${w} · parámetros: {contrato_id: ${triaje.contrato_id}, trace_id: ${traceId}}`),
  ...(revisiones.length ? [`*Enviados a aprobación:* ${revisiones.map((x) => x.mov_id).join(', ')}`] : []),
  `*Respuesta:*`,
  respuesta.slice(0, 1500),
].join('\n');

return [{ json: { respuesta, logSlack, estado, revisiones, hay_revisiones: revisiones.length > 0,
  intencion: triaje.intencion || '', contrato_id: triaje.contrato_id || '', cliente: triaje.cliente || '' } }];

