// Memoria · prepara el contexto que se inyecta en el Manager (sin IA). Solo lee su entrada.
const r = $input.first().json;
const f = r.fields || r;
const parse = (s, d) => { try { return s ? JSON.parse(s) : d; } catch (e) { return d; } };
const limpio = (s) => String(s || '').replace(/[{}]/g, '').trim();
const datos = parse(f['Datos clave'], {});
const resumen = parse(f['Resumen consolidado'], null);

let ultima = 'Sin conversaciones previas.';
if (resumen && resumen.asunto_principal) {
  ultima = `${resumen.asunto_principal}. Puntos clave: ${(resumen.puntos_clave || []).join('; ')}. Acción requerida: ${resumen.accion_requerida || 'ninguna'}.`;
} else if (datos.ultima_peticion) {
  ultima = `Última petición: "${datos.ultima_peticion}" (${datos.ultima_intencion || 'sin clasificar'}, contrato ${datos.contrato_id || '-'}).`;
}
const clave = [
  datos.cliente ? `cliente en curso ${datos.cliente}` : null,
  datos.contrato_id ? `contrato ${datos.contrato_id}` : null,
  (datos.movimientos_en_revision || []).length ? `movimientos en revisión ${datos.movimientos_en_revision.join(', ')}` : null,
  `mensajes en la sesión ${datos.mensajes || 0}`,
].filter(Boolean).join('; ');

return [{ json: {
  session_id: f.Session_ID,
  usuario_nuevo: (f['Estado del caso'] || 'NUEVO') === 'NUEVO' && !datos.mensajes,
  user_name: limpio(datos.usuario || 'equipo de Administración'),
  last_status: f['Estado del caso'] || 'NUEVO',
  last_summary: limpio(ultima),
  datos_clave: limpio(clave),
  resumen_json: f['Resumen consolidado'] || '',
  datos,
} }];

// Memoria · decide qué guardar (sin IA). Nunca guarda la conversación completa.
const c = $input.first().json;
const ctx = $('Contexto de memoria').first().json;
const traza = $('Preparar traza').first().json;
const previos = ctx.datos || {};
const mensajes = Number(previos.mensajes || 0) + 1;

let estado = 'ABIERTO';
if (/REVISIÓN HUMANA/.test(c.estado)) estado = 'PENDIENTE_REVISION';
else if (/ESCALAR/.test(c.estado)) estado = 'ESCALADO';
else if (/FALLO/.test(c.estado)) estado = 'ABIERTO';
else if (/PAGOS REGISTRADOS|ACTUALIZAR|CONSULTAR/.test(c.estado)) estado = 'CERRADO';

const datos = {
  usuario: previos.usuario || 'equipo de Administración',
  cliente: c.cliente || previos.cliente || '',
  contrato_id: c.contrato_id || previos.contrato_id || '',
  ultima_intencion: c.intencion || '',
  ultima_peticion: String(traza.peticion || '').slice(0, 200),
  movimientos_en_revision: (c.revisiones || []).map((r) => r.mov_id),
  mensajes,
};
return [{ json: { session_id: traza.sessionId, estado_caso: estado, datos_clave: JSON.stringify(datos),
  resumen_previo: ctx.resumen_json || '', resumir: mensajes > 5, mensajes } }];
